using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var trainer = new ModelTrainerService();
trainer.TrainAndSave();

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(ModelTrainerService.ModelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with customer JSON");

app.MapPost("/predict", (CustomerInput input,
    PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var customerData = new CustomerData
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory,
    };

    var prediction = pool.Predict(customerData);

    return Results.Ok(new
    {
        WillChurn = prediction.PredictedChurned,
        Confidence = prediction.Probability,
    });
});

app.Run();

